def vgeg(anchors, entities, facts, ops, edges):
    V = {
        'anchor': anchors, 'entity': entities,
        'fact': facts, 'op': ops,
    }
    E = edges  # [(src, dst, rel), ...]
    return {'nodes': V, 'edges': E}

